begin transaction read only;
set local statement_timeout='30s';
with candidates as (
 select 'paymentRecord' type,p.status from commerce.payment_records p join migration.source_documents s on s.legacy_sanity_id=p.legacy_sanity_id where p.backend_owner<>'supabase' and not s.tombstoned and not(coalesce(s.payload->'providerRecoveryTerminal','false'::jsonb)='true'::jsonb and coalesce(s.payload->>'providerRecoveryTerminalReason','') in ('payment_currency_mismatch','payment_currency_invalid')) and (p.provider<>'dodo' or coalesce(s.payload->>'providerRecoveryTerminal','false')<>'true' or p.refund_requires_booking_sync or p.resource_release_pending or (p.status='email_partial' and s.payload->>'requiresReschedule'='true') or(p.status in ('email_partial','booked') and p.email_dispatch_required)) and (p.status in ('started','captured_client','captured_webhook','finalizing','needs_recovery','email_partial') or p.refund_requires_booking_sync or(p.status='booked' and p.email_dispatch_required) or(p.status='abandoned' and(p.resource_release_pending or p.late_capture_watch_until is not null))) and(p.next_recovery_at is null or p.next_recovery_at<=now())
 union all select 'slotHold',h.phase from commerce.slot_holds h join migration.source_documents s on s.legacy_sanity_id=h.legacy_sanity_id cross join migration.commerce_control c where c.singleton and(h.backend_owner<>'supabase' or s.backend_owner<>'supabase') and h.cutover_generation=c.generation and s.cutover_generation=c.generation and h.phase in ('active','payment') and h.expires_at<=now() and s.document_type='slotHold' and not s.tombstoned and lower(coalesce(s.payload->>'phase','active')) in ('active','holding','payment','payment_pending')
 union all select 'rateLimitBucket','expired' from commerce.rate_limit_buckets where backend_owner<>'supabase' and reset_at<=now()
) select type,status,count(*) newly_included from candidates group by 1,2 order by 1,2;
rollback;
